  --primary: hsl(18.08 24.7% 51.79%);
  --primary-foreground: hsl(300 50% 100%);
  --secondary: hsl(37.51 23.4% 65.33%);
  --secondary-foreground: hsl(300 50% 100%);
  --muted: hsl(20.46 46.14% 80.76%);
  --muted-foreground: hsl(13.75 20.66% 44.51%);
  --accent: hsl(20.46 46.14% 80.76%);
  --accent-foreground: hsl(15.67 17.86% 29.65%);
  --destructive: hsl(22.51 15.43% 10.36%);
